/* ===== Terminale ES · Thème 3 · 3.1 La biodiversité et son évolution · Activité 1 « Estimer un effectif par capture-marquage-recapture » : contenus =====
   D'après la fiche du professeur (Th3 Ch1 Act1, méthode CMR) et sa trace écrite. Les questions 7 a-b (moustiques, manuel p. 196) restent sur papier. */
const PROBLEM = "Comment estimer l'effectif d'une population que l'on ne peut pas compter entièrement, et quelle confiance accorder à cette estimation ?";
const tk = ok => ok ? "✓" : "○";
const taskMsg = (ok, msg) => ({ ok, msg });
const big2 = () => bigStd().length, multi1 = () => multiStd().length;
const defi = () => runs().filter(r => r.std && r.est !== null && r.n1 >= 200 && r.n2 >= 200 && r.k >= 3);
const errOf = r => r ? r.err : NaN;
const shownStd = () => done(runs().slice(-12)).filter(r => r.std);

/* ---------- les manipulations attendues ---------- */
const T_MINI = () => taskMsg(!!xst().miniDone, xst().miniDone ? "✓ Expérience réalisée jusqu'à la recapture." : "Expérience pas encore terminée : va jusqu'à « Recapturer ».");
const T_BAL = () => taskMsg(!!xst().bal30, xst().bal30 ? "✓ Tu as trouvé la valeur de N qui égalise les deux proportions." : "Fais varier N jusqu'à ce que les deux proportions soient égales.");
const T_1 = () => { const n = done(stdRuns()).length; return taskMsg(n >= 1, n ? `✓ ${n} CMR vérifiée${n > 1 ? "s" : ""} en conditions idéales.` : hasRun(r => r.std && r.est === null) ? "Ta CMR n'a recapturé aucun poisson marqué (m = 0) : recommence avec un nouvel étang." : hasRun(r => !r.std) ? "Reviens aux conditions idéales (conditions de terrain), puis réalise une CMR jusqu'à « Vérifier »." : "Aucune CMR terminée pour l'instant : va jusqu'à « Vérifier »."); };
const T_3 = () => { const n = sameProto().length; return taskMsg(n >= 3, `${tk(n >= 3)} ${Math.min(n, 3)}/3 CMR avec le même protocole, en conditions idéales.`); };
const T_5 = () => { const a = big2(), b = multi1(); return taskMsg(a >= 2 && b >= 1, `${tk(a >= 2)} grands échantillons (n₁ et n₂ ≥ 150) : ${Math.min(a, 2)}/2 · ${tk(b >= 1)} plusieurs recaptures : ${Math.min(b, 1)}/1 (conditions idéales)`); };
const T_C1 = () => { const a = hasRun(r => r.lose), b = hasRun(r => r.eff === "pred"); return taskMsg(a && b, `${tk(a)} marque qui s'efface · ${tk(b)} héron qui mange les poissons marqués`); };
const T_C2 = () => { const a = hasRun(r => r.w === "h" && r.pl === "near"), b = hasRun(r => r.w === "h" && r.pl === "far"); return taskMsg(a && b, `${tk(a)} 1 heure, même endroit · ${tk(b)} 1 heure, autre bout de l'étang`); };
const T_C3 = () => { const a = hasRun(r => r.birth), b = hasRun(r => r.eff === "shy"); return taskMsg(a && b, `${tk(a)} naissances et arrivées · ${tk(b)} poissons marqués qui évitent le filet`); };
const T_C4 = () => { const L = defi(); return taskMsg(L.length > 0, L.length ? `✓ Défi réussi : écart de ${pc(L[L.length - 1].err)}.` : "Défi pas encore réalisé : conditions idéales, n₁ et n₂ ≥ 200, 3 ou 5 recaptures."); };
const T_D1 = () => { const a = !!serie(50), b = !!serie(200); return taskMsg(a && b, `${tk(a)} série n = 50 · ${tk(b)} série n = 200`); };
const T_D2 = () => { const n = (xst().rv || []).length; return taskMsg(n >= 3, `${tk(n >= 3)} ${Math.min(n, 3)}/3 tailles d'échantillon observées`); };
const T_D3 = () => { const a = !!serie(50), b = !!serie(200), c = !!serie(300); return taskMsg(a && b && c, `${tk(a)} n = 50 · ${tk(b)} n = 200 · ${tk(c)} n = 300`); };

const HOME = { slug: "methode-capture-marquage-recapture", short: "Estimer un effectif par CMR", last: "d4", lastG: "p4", lastK: 3, dur: "environ 1 h 15 (possible en deux séances : parties 1 et 2, puis 3 et 4)",
  kicker: "Thème 3 · Chapitre 1 · La biodiversité et son évolution · Activité 1", title: "Estimer un effectif par capture-marquage-recapture",
  intro: "Dans un étang, une forêt ou une prairie, on ne peut pas compter tous les individus d'une population. Les écologues capturent un échantillon, le marquent, le relâchent, puis recapturent un second échantillon. Tu vas réaliser cette méthode dans un étang simulé, chercher comment réduire l'erreur, tester ce qui se passe quand ses conditions ne sont pas respectées, puis encadrer l'estimation par un intervalle de confiance.",
  lab: "Le problème", goal: "Objectif : estimer un effectif par la méthode CMR, mesurer l'écart avec l'effectif réel, proposer et tester des solutions pour le réduire, repérer les points de vigilance, puis encadrer l'estimation par un intervalle de confiance au niveau de 95 %.",
  fact: "La méthode a été utilisée pour la première fois en écologie en 1896 par le biologiste danois C. G. Johannes Petersen, qui marquait des plies (des poissons plats) pour estimer leur nombre. En 1930, l'Américain Frederick Lincoln l'a appliquée aux canards bagués : on parle encore aujourd'hui de l'estimateur de Lincoln-Petersen.",
  parts: "Les quatre parties de l'activité", recop: "Bilan à recopier dans le cahier",
  txt: "ACTIVITÉ 1 · ESTIMER UN EFFECTIF PAR CAPTURE-MARQUAGE-RECAPTURE (CMR)\nTerminale · Enseignement scientifique · Thème 3 · Chapitre 1 : la biodiversité et son évolution",
  comps: { mod: "Utiliser un logiciel de simulation", lire: "Lire et exploiter des résultats", calc: "Calculer (proportions, quatrième proportionnelle, intervalle)", conn: "Mobiliser ses connaissances", crit: "Exercer son esprit critique (biais, limites)", rais: "Raisonner, argumenter" },
  vers: { g: { icon: "🧭", short: "Guidée", name: "Version guidée", q: "guidee", desc: "Je réponds par des choix, des tableaux à cocher et des valeurs lues dans le laboratoire, avec des pistes pas à pas." },
    l: { icon: "🎓", short: "Exigeante", name: "Version exigeante", q: "exigeante", desc: "Les mêmes manipulations, mais je calcule davantage et je rédige mes réponses : je vois → je sais → j'en déduis." } },
  extraTitle: "Mes simulations",
  extra: () => { const R = runs(), L = series().slice().sort((a, b) => a.n - b.n);
    return `MES CMR DANS LE LABORATOIRE (${R.length})\n` + (R.length ? R.map(r => `- n° ${r.id} : n₁ = ${r.n1}, n₂ = ${r.n2}${r.k > 1 ? ` (${r.k} recaptures, m̄ = ${fmt(Math.round(r.mb * 100) / 100)})` : `, m = ${r.ms[0]}`} → ${r.est === null ? "estimation impossible" : "N̂ = " + nI(r.est)} ; N réel = ${nI(r.N)}${r.err === null ? "" : ` ; écart ${pc(r.err)}`} ; conditions : ${condTxt(r)}`).join("\n") : "- aucune") +
      `\n\nMES SÉRIES DE 50 CMR (N = ${nI(NTEST)})\n` + (L.length ? L.map(s => { const t = sStats(s); return `- n = ${s.n} : ${t.imp} impossible(s), N̂ de ${t.min === null ? "—" : nI(t.min)} à ${t.max === null ? "—" : nI(t.max)}, ${pc(t.within)} à moins de 10 % de N, ${pc(t.cont)} des intervalles contiennent N`; }).join("\n") : "- aucune") + "\n"; },
  extraHTML: () => `<p class="kicker">Laboratoire</p>${runsTable()}<p class="kicker">Séries de 50 CMR</p>${fluTable(false)}${series().length ? fluTable(true) : ""}` };

/* ---------- documents et simulateurs ---------- */
const W_MINI = { title: "Animation · Le petit étang", w: "mini", sim: "Valeurs simulées" };
const W_BAL = { title: "Manipulation · La balance des proportions", w: "balance" };
const W_LAB = { title: "Laboratoire · L'étang aux poissons", w: "lab", sim: "Valeurs simulées" };
const W_LABC = { title: "Laboratoire · L'étang aux poissons, conditions de terrain", w: "labc", sim: "Valeurs simulées" };
const W_FLU = { title: "Simulateur · 50 CMR identiques", w: "flu", sim: "Valeurs simulées" };
const W_FLUIC = { title: "Simulateur · Les intervalles de confiance de 50 CMR", w: "fluic", sim: "Valeurs simulées" };
const W_RUL = { title: "Manipulation · La demi-largeur 1/√n", w: "ruler" };
const DOC1 = { title: "Document 1 · Le protocole de la capture-marquage-recapture", html: `<ol class="ul"><li><b>Capture</b> : on capture un premier échantillon de <b>n₁</b> individus.</li><li><b>Marquage</b> : on marque chaque individu (bague, pastille, petite entaille de nageoire…) sans le blesser, puis on le relâche là où il a été capturé.</li><li><b>Attente</b> : on laisse aux individus marqués le temps de se mélanger au reste de la population.</li><li><b>Recapture</b> : on capture un second échantillon de <b>n₂</b> individus et on compte, parmi eux, les <b>m</b> individus marqués.</li></ol><p class="cap">n₁, n₂ et m sont comptés par l'écologue. L'effectif N de la population reste inconnu : c'est lui que l'on cherche à estimer.</p>` };
const DOCH = { title: "Document 2 · L'hypothèse de la méthode", html: `<p>Si les individus marqués se sont bien mélangés à la population, un échantillon pris au hasard en contient <b>la même proportion</b> que la population entière.</p>${tbl(["", "Individus marqués", "Effectif total"], [["Échantillon de recapture", "m", "n₂"], ["Population entière", "n₁", "N (inconnu)"]])}<p class="cap">Ce tableau est un tableau de proportionnalité : N en est la quatrième proportionnelle.</p>` };
const DOCP = { title: "Document 3 · Mode d'emploi du laboratoire", html: `<ol class="ul"><li>Règle <b>n₁</b> (poissons capturés puis marqués), <b>n₂</b> (poissons recapturés) et le nombre de recaptures.</li><li>Touche l'étang pour placer ton filet (sinon, il est lancé au hasard), puis suis les étapes : Capturer → Marquer → Attendre → Recapturer.</li><li>Dans le <b>carnet de terrain</b>, calcule l'estimation <b>N̂ = n₁ × n₂ ÷ m</b> (les deux premières fois ; ensuite, le calcul devient automatique).</li><li>Touche <b>Révéler l'effectif réel</b> : en simulation, on peut vider l'étang et compter tous les poissons. Sur le terrain, c'est impossible.</li><li><b>Écart (en %) = |N̂ − N| ÷ N × 100</b>. Chaque simulation s'ajoute au tableau « Mes simulations ».</li></ol><p class="cap">Chaque nouvel étang contient entre 300 et 900 poissons : l'effectif change d'une simulation à l'autre.</p>` };
const DOCV = { title: "Document 4 · Les conditions de terrain du laboratoire", html: `<ul class="ul"><li><b>Temps d'attente</b> : 1 heure, 1 jour ou 1 semaine. Pendant l'attente, les poissons nagent au hasard.</li><li><b>Lieu de la recapture</b> : au hasard, au même endroit que la capture, ou à l'autre bout de l'étang.</li><li><b>La marque</b> : permanente, ou bien elle s'efface chez un poisson marqué sur deux pendant l'attente.</li><li><b>Effet de la marque</b> : aucun ; ou le héron repère la pastille et mange un poisson marqué sur deux ; ou les poissons marqués, effrayés, évitent le filet 7 fois sur 10.</li><li><b>La population</b> : constante, ou + 60 % de poissons pendant l'attente (naissances, arrivées par le ruisseau).</li></ul><div class="box key"><p class="lab">✔ Démarche</p><p>Pour savoir quel est l'effet d'une condition, n'en modifie qu'<b>une seule à la fois</b> (les autres restent idéales) et prends des échantillons assez grands : n₁ = n₂ = 150.</p></div><p class="cap">⚠ Valeurs d'un modèle simplifié.</p>` };
const DOCI = { title: "Document 5 · Encadrer une estimation : l'intervalle de confiance", html: `<p>Sur un échantillon de taille n, on mesure la fréquence f d'un caractère. Au <b>niveau de confiance de 95 %</b>, la proportion p de ce caractère dans toute la population est comprise dans l'intervalle :</p><p class="eq">[ f − 1/√n ; f + 1/√n ]</p><p>En CMR : f = m ÷ n₂ (proportion de marqués dans la recapture), n = n₂ et p = n₁ ÷ N. Comme N = n₁ ÷ p, on obtient l'intervalle de N en divisant n₁ par les bornes de l'intervalle de f. Attention : la plus grande borne de f donne la plus petite valeur de N. Si f − 1/√n est négatif ou nul, l'intervalle de N n'a pas de borne supérieure.</p><div class="box info"><p class="lab">ℹ Données</p><p>Dans un étang de pisciculture, 120 gardons sont capturés, marqués puis relâchés. Une semaine plus tard, 150 gardons sont recapturés, dont 30 marqués.</p></div><p class="cap">⚠ Données fictives.</p>` };
const DOCR = { title: "Document 6 · Mes résultats", w: "recap" };

/* ---------- bilan à recopier ---------- */
const BIL = [
  "L'<u>abondance</u> d'une population (son effectif) s'estime à partir d'<u>échantillons</u>. Méthode de <u>capture-marquage-recapture (CMR)</u> : on capture et on marque n₁ individus, on les relâche, on attend qu'ils se mélangent à la population, puis on recapture n₂ individus, dont m sont marqués.",
  "<u>Hypothèse</u> : la proportion d'individus marqués est la même dans l'échantillon de recapture et dans la population entière : m ÷ n₂ = n₁ ÷ N. Par le calcul d'une <u>quatrième proportionnelle</u> : <u>N̂ = n₁ × n₂ ÷ m</u>.",
  "Le résultat est une <u>estimation</u> : à cause du hasard de l'échantillonnage (<u>fluctuation d'échantillonnage</u>), N̂ change d'une CMR à l'autre. Pour réduire l'écart : de <u>grands échantillons</u> et <u>plusieurs recaptures</u> (moyenne de m).",
  "<u>Points de vigilance</u> : marque permanente, qui ne modifie ni la survie ni le comportement ; temps suffisant pour que les individus marqués se mélangent à la population ; population constante (ni naissance, ni mort, ni migration) ; capture reproductible, qui prend au hasard marqués et non marqués. Sinon, l'estimation est <u>biaisée</u> (sur- ou sous-estimation).",
  "<u>Intervalle de confiance au niveau de 95 %</u> d'une proportion f mesurée sur un échantillon de taille n : [f − 1/√n ; f + 1/√n]. En CMR, f = m ÷ n₂ et N = n₁ ÷ f : N est compris entre n₁ ÷ (f + 1/√n₂) et n₁ ÷ (f − 1/√n₂). Une estimation n'est jamais sûre à 100 % ; elle est d'autant plus <u>précise</u> que l'échantillon est <u>grand</u>."];
const bilanHTML = () => BIL.map(x => `<p>${nb(x)}</p>`).join("");

/* ---------- critères de repérage communs (réponses rédigées) ---------- */
const FORM = (T, n) => /n ?(₁|1) ?(×|x|\*|fois) ?n ?(₂|2) ?(\/|÷|sur|divise par) ?m/.test(n) || /n ?(₂|2) ?(×|x|\*|fois) ?n ?(₁|1) ?(\/|÷|sur|divise par) ?m/.test(n) || /quatrieme proportionnelle/.test(n);
const SUR = /(sur-?estim|trop grand|trop elev|plus grand|superieur|plus eleve|plus important|surevalu)/;
const SOUS = /(sous-?estim|trop petit|trop faible|plus petit|inferieur|sous-?evalu)/;

